UPDATE lessons SET title='Year 4, Week 20, Lesson 1: Positive relationships online', data=json_patch(data,'{"child_mission":"Positive relationships online use kind words, privacy (no sharing others’ images without permission), and pause–block–tell for unkind behaviour.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhich are safe: posting a friend’s address; asking before posting their photo; sharing a rumour because it’s funny?\n\nFEEDBACK\nUnsafe; safe; unsafe.\n\nWATCH FOR\n“Just online” does not make cruelty OK.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCreate an online respect charter with eight pledges including privacy and reporting.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Positive relationships online use kind words, privacy (no sharing others’ images without permission), and pause–block–tell for unkind behaviour.","lesson_number":1,"lesson_role":"Learn and discuss","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-RRS-02"],"parent_notes":"Parent: Marking guidance for the independent task: Create an online respect charter with eight pledges including privacy and reporting. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Unsafe; safe; unsafe. Reasoning: I used online by attending to respect rather than copying the worked model.\n\nParent: Written model 2: Common error: “Just online” does not make cruelty OK. Correction: Unsafe; safe; unsafe. Why: the correction restores accurate use of online.\n\nParent: Likely misconception: “Just online” does not make cruelty OK. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating online on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with online, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Require independently produced work with a specific supporting detail. / Require misconception + correction + purpose-linked reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"Unsafe; safe; unsafe. This matches the lesson skill for online.","options":["Copy the example and call that independent work.","Unsafe; safe; unsafe.","“Just online” does not make cruelty OK.","Ignore the safety rule because the first idea looked exciting."],"question":"Which are safe: posting a friend’s address; asking before posting their photo; sharing a rumour because it’s funny?","type":"multiple_choice"},{"correct_index":2,"explanation":"“Just online” does not make cruelty OK. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Unsafe; safe; unsafe.","Careful use of respect with clear evidence.","“Just online” does not make cruelty OK.","Positive relationships online use kind words, privacy (no sharing others’ images without permission), and pause–block–tell for unkind behaviour."],"question":"Which statement is a common mistake when practising online?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and named respect, not by copying the model.","options":["Repeat the worked example wording with no new evidence.","Choose randomly because any option could be right.","Treat a skipped permission or safety step as if it did not matter.","Apply the idea with new evidence and name the respect used."],"question":"A learner is practising online. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":1,"explanation":"Unsafe; safe; unsafe. uses safe, healthy, respectful choices appropriately for this lesson.","options":["Copy the example and call that independent work.","Unsafe; safe; unsafe.","“Just online” does not make cruelty OK.","Ignore the safety rule because the first idea looked exciting."],"question":"Which response best shows careful thinking about online?","type":"multiple_choice"},{"correct_index":0,"explanation":"Strong answers name specific evidence and what it shows.","options":["Name a specific source, cue or example and say what it shows about online.","Make a bigger claim without naming any source or cue.","Copy a classmate’s sentence with no local detail.","“Just online” does not make cruelty OK."],"question":"Which habit strengthens evidence about respect?","type":"multiple_choice"},{"correct_index":0,"explanation":"The stronger choice matches the taught idea with concrete detail.","options":["Example: ask before tagging; no password sharing; screenshot+tell adult if threats.","“Just online” does not make cruelty OK.","Treat a skipped permission or safety step as if it did not matter.","Ignore the safety rule because the first idea looked exciting."],"question":"Using this lesson idea — Positive relationships online use kind words, privacy (no sharing others’ images without permission), and… — which choice is best?","type":"multiple_choice"},{"correct_index":3,"explanation":"Respect and accuracy mean checking evidence and honouring limits/protocols.","options":["Invent missing details to make the answer sound complete.","Ignore safety or cultural protocols to finish faster.","Treat every online claim as equally reliable.","Check facts/cues, acknowledge limits, and avoid inventing details."],"question":"Which action shows respect and accuracy together?","type":"multiple_choice"},{"correct_index":0,"explanation":"Independence requires a new example that still uses the skill.","options":["Create an online respect charter with eight pledges including privacy and reporting.","Retype the worked example with no new example.","Copy the example and call that independent work.","“Just online” does not make cruelty OK."],"question":"Which task best shows independent use of online?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require independently produced work with a specific supporting detail.","question":"Produce a fresh example demonstrating online on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Original response on new material: Unsafe; safe; unsafe. Reasoning: I used online by attending to respect rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require misconception + correction + purpose-linked reason.","question":"Name one likely error with online, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Common error: “Just online” does not make cruelty OK. Correction: Unsafe; safe; unsafe. Why: the correction restores accurate use of online.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y4-w20-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise online.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Health, Wellbeing and Relationships","success_criteria":["I can use online with a specific example from this lesson.","I can identify respect and explain why it matters.","I can practise privacy independently on a new prompt.","I can notice kind needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":1,"explanation":"Positive relationships online use kind words, privacy (no sharing others’ images without permission), and pause–block–tell for unkind behaviour. Supported choices follow the actual cues, rules and purpose of the task.","options":["A guess with no reason.","Positive relationships online use kind words, privacy (no sharing others’ images without permission), and pause–block–tell for unkind behaviour.","A choice unrelated to safety, health or respect.","An answer copied without understanding."],"question":"Which choice best shows accurate use of this idea about online?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: ask before tagging; no password sharing; screenshot+tell adult if threats.\n\nTRY FIRST\nWhich are safe: posting a friend’s address; asking before posting their photo; sharing a rumour because it’s funny?\n\nFEEDBACK\nUnsafe; safe; unsafe.","explain":"Positive relationships online use kind words, privacy (no sharing others’ images without permission), and pause–block–tell for unkind behaviour.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"“Just online” does not make cruelty OK. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Positive online relationships.","caption":"Ask before posting others.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Online</text><text x=\"28\" y=\"78\">kind + private</text><text x=\"358\" y=\"42\">Pause block tell</text><text x=\"358\" y=\"78\">unkind content</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example: ask before tagging; no password sharing; screenshot+tell adult if threats. Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example: ask before tagging; no password sharing; screenshot+tell adult if threats. Then write your own reasons."}}]},{"check":{"correct_index":2,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others. Supported choices follow the actual cues, rules and purpose of the task.","options":["An answer copied without understanding.","A guess with no reason.","Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.","A choice unrelated to safety, health or respect."],"question":"Which choice best shows accurate use of this idea about online?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: ask before tagging; no password sharing; screenshot+tell adult if threats. Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"Respect charter.","caption":"Report path.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Eight pledges</text><text x=\"28\" y=\"78\">privacy</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">just online excuse</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice. Supported choices follow the actual cues, rules and purpose of the task.","options":["An answer copied without understanding.","A guess with no reason.","Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.","A choice unrelated to safety, health or respect."],"question":"Which choice best shows accurate use of this idea about online?","type":"multiple_choice"},"example":"WORKED MODEL\n“Just online” does not make cruelty OK. Here is a more helpful example: Example: ask before tagging; no password sharing; screenshot+tell adult if threats.\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nUnsafe; safe; unsafe.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. “Just online” does not make cruelty OK. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":2,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion. Supported choices follow the actual cues, rules and purpose of the task.","options":["An answer copied without understanding.","A guess with no reason.","Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.","A choice unrelated to safety, health or respect."],"question":"Which choice best shows accurate use of this idea about online?","type":"multiple_choice"},"example":"WORKED MODEL\nPositive relationships online use kind words, privacy (no sharing others’ images without permission), and pause–block–tell for unkind behaviour. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 4, Week 20, Lesson 1: Positive relationships online","unit_number":4,"unit_title":"Relationships, communication and respect","week":20,"week_in_unit":5,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: ask before tagging; no password sharing; screenshot+tell adult if threats.\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Positive online relationships.","caption":"Ask before posting others.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Online</text><text x=\"28\" y=\"78\">kind + private</text><text x=\"358\" y=\"42\">Pause block tell</text><text x=\"358\" y=\"78\">unkind content</text></g></svg>"},{"alt":"Respect charter.","caption":"Report path.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Eight pledges</text><text x=\"28\" y=\"78\">privacy</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">just online excuse</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-pdhpe-y4-w20-l1' AND family_id IS NULL;
